import {createStudy,canvasSurface,clamp,downloadCanvas} from './core.js';
const study=createStudy({id:10,title:'Palimpsest',category:'Typography / Memory',accent:'#ff8068',background:'#171444',foreground:'#f0e9d9'});
const canvas=document.querySelector('#palimpsest-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5});
const memoryCanvas=document.createElement('canvas'),memory=memoryCanvas.getContext('2d');let lastW=0,lastH=0,lastPoint=null,brush='TRACE',lifespan=6,retain=false,count=0,queue=[];
function resize(){lastW=surface.width;lastH=surface.height;memoryCanvas.width=canvas.width;memoryCanvas.height=canvas.height;memory.setTransform(surface.dpr,0,0,surface.dpr,0,0);queue=[];lastPoint=null}
function stamp(mark){const char=brush[count%brush.length]||'✳';memory.save();memory.translate(mark.x,mark.y);memory.rotate(mark.angle);memory.fillStyle=count%5===0?'#f0e9d9':'#ff8068';memory.font=`700 ${mark.size}px Display, sans-serif`;memory.textAlign='center';memory.textBaseline='middle';memory.fillText(char,0,0);memory.restore();count++;document.querySelector('#palimpsest-counter').textContent=String(count).padStart(3,'0')+' TRACES'}
function draw({dt=0,time=0}={}){if(lastW!==surface.width||lastH!==surface.height)resize();const {ctx,width:w,height:h,dpr}=surface;if(study.running()&&!retain&&dt){memory.save();memory.globalCompositeOperation='destination-out';memory.fillStyle=`rgba(0,0,0,${Math.min(.1,dt/lifespan*3)})`;memory.fillRect(0,0,w,h);memory.restore()}while(queue.length)stamp(queue.shift());ctx.fillStyle='#171444';ctx.fillRect(0,0,w,h);const fontSize=Math.min(w*.18,h*.23),centerY=h*.46-(w<650?28:0);ctx.font=`700 ${fontSize}px Display, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';const first='SOMETHING',second='REMAINS.';const max=Math.max(ctx.measureText(first).width,ctx.measureText(second).width),scale=Math.min(1,(w-65)/Math.max(1,max));ctx.font=`700 ${fontSize*scale}px Display, sans-serif`;for(let i=13;i>=0;i--){const x=w/2+(i-6)*3.1,y=centerY+(i-6)*3.4;ctx.strokeStyle=i===0?'#ff8068':`rgba(255,128,104,${.08+i*.013})`;ctx.lineWidth=.8;ctx.strokeText(first,x,y-fontSize*.39);ctx.strokeText(second,x,y+fontSize*.45)}ctx.fillStyle='#f0e9d9';ctx.fillText(first,w/2-18,centerY-fontSize*.39-20);ctx.fillStyle='#ff8068';ctx.fillText(second,w/2-18,centerY+fontSize*.45-20);ctx.save();ctx.globalAlpha=.97;ctx.drawImage(memoryCanvas,0,0,w*dpr,h*dpr,0,0,w,h);ctx.restore();ctx.strokeStyle='#8f84ae35';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.18,130);ctx.lineTo(w*.18,h-180);ctx.moveTo(w*.82,130);ctx.lineTo(w*.82,h-180);ctx.stroke()}
function move(event){const r=canvas.getBoundingClientRect(),x=event.clientX-r.left,y=event.clientY-r.top;document.querySelector('#palimpsest-position').textContent=`X ${Math.round(x).toString().padStart(3,'0')} / Y ${Math.round(y).toString().padStart(3,'0')}`;if(!lastPoint){lastPoint={x,y,t:event.timeStamp};return}const dx=x-lastPoint.x,dy=y-lastPoint.y,d=Math.hypot(dx,dy),elapsed=Math.max(8,event.timeStamp-lastPoint.t);if(d<12)return;if(study.running()||event.buttons){const speed=d/elapsed;queue.push({x,y,angle:Math.atan2(dy,dx)*.18,size:clamp(20+speed*54,20,150)});if(queue.length>8)queue.shift();if(!study.running())study.invalidate()}lastPoint={x,y,t:event.timeStamp}}
canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerdown',event=>{canvas.setPointerCapture(event.pointerId);const r=canvas.getBoundingClientRect();queue.push({x:event.clientX-r.left,y:event.clientY-r.top,angle:0,size:90});study.invalidate()});canvas.addEventListener('pointerleave',()=>lastPoint=null);
document.querySelector('#palimpsest-word').addEventListener('input',event=>{brush=event.target.value.toUpperCase()||'TRACE'});document.querySelector('#palimpsest-memory').addEventListener('input',event=>{lifespan=Number(event.target.value);document.querySelector('#palimpsest-memory-value').textContent=lifespan+' seconds'});document.querySelector('#palimpsest-retain').addEventListener('click',event=>{retain=!retain;event.currentTarget.setAttribute('aria-pressed',String(retain));event.currentTarget.innerHTML=retain?'LET TIME IN <span aria-hidden="true">↘</span>':'KEEP THE TRACES <span aria-hidden="true">↗</span>';study.invalidate()});
function clear(){memory.clearRect(0,0,surface.width,surface.height);queue=[];count=0;lastPoint=null;document.querySelector('#palimpsest-position').textContent='X — / Y —';document.querySelector('#palimpsest-counter').textContent='000 TRACES';study.invalidate()}
document.querySelector('#palimpsest-clear').addEventListener('click',clear);study.onResize(()=>{surface.resize();resize();study.invalidate()});study.onFrame(draw);study.setReset(()=>{brush='TRACE';lifespan=6;retain=false;document.querySelector('#palimpsest-word').value='TRACE';document.querySelector('#palimpsest-memory').value='6';document.querySelector('#palimpsest-memory-value').textContent='6 seconds';const button=document.querySelector('#palimpsest-retain');button.setAttribute('aria-pressed','false');button.innerHTML='KEEP THE TRACES <span aria-hidden="true">↗</span>';clear()});study.setExport(()=>downloadCanvas(canvas,'10-palimpsest.png'));study.cleanup(()=>surface.dispose());document.fonts.load('700 100px Display').then(()=>study.invalidate());
